def validate(result,future):
 assert result['schema']=='KRENN_X5_REP4_ALL162_TERMINAL_PROMOTION_CONDITIONAL_DESIGN_V1' and result['status']=='HELD_PROMOTION_FOUR_FUTURE_PASS_SEALS_ABSENT';c=result['authoritative_contraction'];assert c['raw_charts']==972 and c['canonical_s3_charts']==162 and c['members_per_chart']==6 and c['y_groups']==c['z_groups']==81 and c['y_raw']==c['z_raw']==486 and c['independent_referee_pass'] is True
