 expected=[[0],list(range(1,26)),list(range(26,76)),list(range(76,126)),list(range(126,162))];assert [s['group_ids'] for s in result['closure_shards']]==expected;flat=sum(expected,[]);assert flat==list(range(162)) and len(flat)==len(set(flat))==162 and result['prospective_union_proof']=={'group_count':162,'union':list(range(162)),'duplicates':[],'missing':[],'extra':[],'all_four_future_required':True}
 transport=result['raw_s3_transport'];assert [x['group_id'] for x in transport]==list(range(162)) and all(x['raw_member_count']==len(x['raw_s3_members'])==6 for x in transport);raw=[tuple(m) for x in transport for m in x['raw_s3_members']];assert len(raw)==len(set(raw))==972 and sum(x['family']=='y' for x in transport)==sum(x['family']=='z' for x in transport)==81 and sum(m[4]=='y' for m in raw)==sum(m[4]=='z' for m in raw)==486
 scope=result['scope'];assert scope['representative']=='rep4 only' and scope['cross_representative_transport'] is False and scope['other_representatives_closed']==[] and scope['full_conjecture'] is False and scope['promotion_currently_authorized'] is False and scope['solver_runs']==0
 assert future['status']=='UNSATISFIED_FOUR_NULL_HASH_PAIRS' and future['sealed_group0'] is True and future['satisfied'] is False and [d['group_ids'] for d in future['dependencies']]==expected[1:] and all(d['manifest_sha256'] is d['result_sha256'] is None and d['satisfied'] is False for d in future['dependencies'])
