reject('missing_group',lambda r,f:r['closure_shards'][2]['group_ids'].pop());reject('duplicate_group',lambda r,f:r['closure_shards'][3]['group_ids'].__setitem__(0,75));reject('extra_group',lambda r,f:r['closure_shards'][4]['group_ids'].append(162));reject('group0_unsealed',lambda r,f:r['sealed_group0'].__setitem__('dependency_hashes_null',True));reject('group0_wrong_chart',lambda r,f:r['sealed_group0']['chart'].__setitem__(4,'z'));reject('rank_zero_scope_removed',lambda r,f:r['rank_zero_structural_branch'].__setitem__('scope',[]));reject('rank_zero_expanded',lambda r,f:r['rank_zero_structural_branch'].__setitem__('scope',[0,1]));reject('missing_raw_member',lambda r,f:r['raw_s3_transport'][0]['raw_s3_members'].pop());reject('duplicate_raw_member',lambda r,f:r['raw_s3_transport'][1]['raw_s3_members'].__setitem__(0,r['raw_s3_transport'][0]['raw_s3_members'][0]));reject('drop_y_group',lambda r,f:r['raw_s3_transport'][0].__setitem__('family','z'));first_z=next(i for i,x in enumerate(result['raw_s3_transport']) if x['family']=='z');reject('drop_z_raw',lambda r,f:r['raw_s3_transport'][first_z]['raw_s3_members'][0].__setitem__(4,'y'));reject('cross_rep_transport',lambda r,f:r['scope'].__setitem__('cross_representative_transport',True));reject('other_rep_closed',lambda r,f:r['scope'].__setitem__('other_representatives_closed',[1]));reject('full_conjecture',lambda r,f:r['scope'].__setitem__('full_conjecture',True));reject('future_null_treated_satisfied',lambda r,f:f.__setitem__('satisfied',True));reject('future_hash_injected',lambda r,f:f['dependencies'][0].__setitem__('manifest_sha256','0'*64));assert len(tests)==16 and all(tests.values())
out={'schema':'KRENN_X5_REP4_ALL162_PROMOTION_HOSTILE_TESTS_V1','status':'PASS_EXACT_LEDGER_AND_16_HOSTILES','design_sha256':sha(HERE/'results_terminal_promotion_design.json'),'future_dependencies_sha256':sha(HERE/'future_dependencies.json'),'hostile_tests':tests,'hostile_count':16,'solver_runs':0};tmp=HERE/'results_hostile_tests.json.tmp';tmp.write_text(json.dumps(out,indent=2,sort_keys=True)+'\n');os.replace(tmp,HERE/'results_hostile_tests.json');print(json.dumps({'status':out['status'],'hostiles':16,'solver_runs':0},sort_keys=True))
